      if (a === 'fa') { await invoiceShipment(db.get('shipments', b.dataset.id)); return app.refresh(); }
      const s = db.get('so', b.dataset.id);
      if (a === 'onay') { s.status = 'acik'; db.log('Bayi siparişi onaylandı', s.no); const c = cus(s.cust); if (c.phone) NS.smsLog(db, { to: c.phone, name: c.name, text: `${S().bizName || ''}: ${s.no} numaralı siparişiniz onaylandı. Termin ${NS.date(s.due)}.`, kind: 'b2b' }, true); db.save(); toast('Sipariş onaylandı, bayiye SMS gönderildi', 'ok'); return app.refresh(); }
      if (a === 'sv') shipModal(app, s); else if (a === 'ed') soEditor(app, s);
